// Worker entry: OpenNext's fetch handler plus a daily cron that syncs every bank connection
// (papra's sync-bank-connections task, here as a Cloudflare Cron Trigger).
import { drizzle } from "drizzle-orm/d1";

// @ts-ignore generated by `opennextjs-cloudflare build` (absent until the first build)
import { default as openNext } from "./.open-next/worker.js";
import * as schema from "./src/server/db/schema";
import { syncAllConnections } from "./src/server/finance/connections";

// @ts-ignore generated by `opennextjs-cloudflare build` (absent until the first build)
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

type Env = CloudflareEnv & { BETTER_AUTH_SECRET: string };

export default {
  fetch: (openNext as ExportedHandler<Env>).fetch,

  async scheduled(_controller, env, ctx) {
    const db = drizzle(env.DB, { schema });
    ctx.waitUntil(
      syncAllConnections(db, env.BETTER_AUTH_SECRET).then((results) => {
        const failed = results.filter((r) => !r.ok);
        console.log(`bank sync: ${results.length - failed.length} ok, ${failed.length} failed`, failed);
      }),
    );
  },
} satisfies ExportedHandler<Env>;
